    public static function key(string $source): string { return 'invoice_reminder_'.substr(hash('sha256',$source),0,24); }
    public static function messages(string $locale): array
    {
        $english=explode('-',$locale,2)[0]==='en';$messages=[];
        foreach(self::ENGLISH as$source=>$translation)$messages[self::key($source)]=$english?$translation:$source;
        return $messages;
    }
    public static function text(string $source,array $messages): string
    {
        if(preg_match('/\AFür diese Originalrechnung fehlen nachweisbare Erinnerungswerte: (.+)\. Ganze Texte gezielt berichtigen\.\z/u',$source,$match)){
            $template='Für diese Originalrechnung fehlen nachweisbare Erinnerungswerte: {values}. Ganze Texte gezielt berichtigen.';
            return str_replace('{values}',$match[1],$messages[self::key($template)]??$template);
        }
        return $messages[self::key($source)]??TextSettingsMessages::text($source,$messages);
    }
}
